import {createTRPCClient, httpBatchLink} from '@trpc/client';
import type {AppRouter, PrivateRouter} from '../../bff/trpc';

export const getTRPCClient = (baseUrl: string) => {
  return createTRPCClient<AppRouter & PrivateRouter>({
    links: [httpBatchLink({url: `${baseUrl}/bff`})],
  });
};

import type {StackContext} from 'sst/constructs';
import {Api, use} from 'sst/constructs';
import {AppConfig} from './AppConfig';

type Routes = Record<
  string,
  {function: {handler: string; timeout?: number; memorySize?: number}}
>;

export function BffApi({stack}: StackContext) {
  const {hostedZone, target, featureAppName} = use(AppConfig);
  const baseUrl = `/__app__/${featureAppName}/${target}`;
  const privateBaseUrl = `/__app-private__/${featureAppName}/${target}`;
  const routes: Routes = {
    [`ANY ${baseUrl}/bff/{proxy+}`]: {
      function: {
        handler: `src/bff/trpc.handler`,
      },
    },
    [`ANY ${privateBaseUrl}/bff/{proxy+}`]: {
      function: {
        handler: `src/bff/trpc.privateHandler`,
      },
    },
  };

  const api = new Api(stack, `api`, {
    customDomain: {
      hostedZone,
      domainName: [`stage`, `dev`, `prod`].includes(stack.stage)
        ? `bff.${hostedZone}`
        : `bff.${stack.stage}.${hostedZone}`,
    },
    routes,
  });

  stack.addOutputs({
    apiUrl: api.customDomainUrl ?? api.url,
  });

  return api;
}

import * as aws from 'aws-cdk-lib';
import * as cloudfront from 'aws-cdk-lib/aws-cloudfront';
import * as origins from 'aws-cdk-lib/aws-cloudfront-origins';
import * as lambda from 'aws-cdk-lib/aws-lambda';
import type {StackContext} from 'sst/constructs';
import {Bucket, StaticSite, use} from 'sst/constructs';
import {AppConfig} from './AppConfig';
import {BffApi} from './BffApi';

export function Site({stack, app}: StackContext) {
  const {hostedZone, target} = use(AppConfig);
  const baseUrl = `/__app__/${app.name}/${target}`;
  const privateBaseUrl = `/__app-private__/${app.name}/${target}`;
  const api = use(BffApi);

  const originRewrite = new cloudfront.experimental.EdgeFunction(
    stack,
    `OriginRewriteEdge`,
    {
      code: lambda.Code.fromInline(`
      exports.handler = async (event) => {
        console.debug("event", JSON.stringify(event));

        const request = event.Records[0].cf.request;
        const [, , appName, appVersion] = request.uri.split("/");

        const domainName = appVersion + "." + appName + ".feature-app.srv.smart.com";

        request.origin.custom.domainName = domainName;
        request.headers["host"] = [{ key: "Host", value: domainName }];

        console.debug("request", JSON.stringify(request));

        return request;
      };
      `),
      runtime: lambda.Runtime.NODEJS_LATEST,
      handler: `index.handler`,
      stackId: app.logicalPrefixedName(`origin-rewrite`),
    },
  );

  const bucket = new Bucket(stack, `frontend-bucket`, {
    blockPublicACLs: true,
    cdk: {
      bucket: {
        autoDeleteObjects: true,
        removalPolicy: aws.RemovalPolicy.DESTROY,
      },
    },
  });
  const S3Origin = new origins.S3Origin(bucket.cdk.bucket);
  const site = new StaticSite(stack, `frontend`, {
    buildOutput: `build`,
    buildCommand: `npx pnpm run build`,
    environment: {
      BASE_URL: baseUrl,
    },
    dev: {
      url: `http://localhost:${process.env.PORT ?? 3000}`,
    },
    customDomain: {
      hostedZone,
      domainName: hostedZone,
    },
    assets: {
      fileOptions: [
        {
          files: [`**/feature-app.js`],
          cacheControl: `max-age=31536000, public, immutable`,
        },
      ],
    },
    cdk: {
      bucket: bucket.cdk.bucket,
      distribution: {
        defaultBehavior: {
          origin: S3Origin,
        },
        additionalBehaviors: {
          [`${baseUrl}/bff/*`]: {
            origin: new origins.HttpOrigin(aws.Fn.parseDomainName(api.url)),
            allowedMethods: cloudfront.AllowedMethods.ALLOW_ALL,
            cachePolicy: cloudfront.CachePolicy.CACHING_DISABLED,
            viewerProtocolPolicy:
              cloudfront.ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
            originRequestPolicy:
              cloudfront.OriginRequestPolicy.ALL_VIEWER_EXCEPT_HOST_HEADER,
          },
          [`${privateBaseUrl}/bff/*`]: {
            origin: new origins.HttpOrigin(aws.Fn.parseDomainName(api.url)),
            allowedMethods: cloudfront.AllowedMethods.ALLOW_ALL,
            cachePolicy: cloudfront.CachePolicy.CACHING_DISABLED,
            viewerProtocolPolicy:
              cloudfront.ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
            originRequestPolicy:
              cloudfront.OriginRequestPolicy.ALL_VIEWER_EXCEPT_HOST_HEADER,
          },
          [`/__app__/${app.name}/*`]: {
            origin: S3Origin,
            cachePolicy: cloudfront.CachePolicy.CACHING_DISABLED,
            viewerProtocolPolicy:
              cloudfront.ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
            originRequestPolicy:
              cloudfront.OriginRequestPolicy.ALL_VIEWER_EXCEPT_HOST_HEADER,
          },
          [`/__app__/*`]: {
            origin: new origins.HttpOrigin(`smart.com`),
            cachePolicy: cloudfront.CachePolicy.CACHING_DISABLED,
            originRequestPolicy:
